function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*7919+13);var tasks=[];for(var i=0;i<8;i++){tasks.push({id:'t'+(i+1),cpu:2+((R()*8)|0),dl:15+((R()*35)|0)});}var nodes=[{name:'eco',w:90},{name:'balanced',w:140},{name:'turbo',w:220}];tasks.sort(function(a,b){return a.dl-b.dl;});var energy=0,t=0,ontime=0,missed=0;tasks.forEach(function(x){var pick=nodes[nodes.length-1];for(var k=0;k<nodes.length;k++){if(t+x.cpu<=x.dl){pick=nodes[k];break;}}t+=x.cpu;energy+=pick.w*x.cpu/1000;if(t<=x.dl){ontime++;}else{missed++;}});return{tasks_scheduled:tasks.length,energy_kwh:+energy.toFixed(3),ontime:ontime,missed:missed,ontime_pct:+(100*ontime/tasks.length).toFixed(1)};}
var SEED = 76501;
console.log(JSON.stringify(demoRun(SEED), null, 1));

